  -webkit-mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 360 420' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M180 0 C280 0, 360 40, 360 120 L360 360 C360 400, 310 420, 180 420 C50 420, 0 400, 0 360 L0 120 C0 40, 80 0, 180 0 Z' fill='black'/%3E%3C/svg%3E");
  mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 360 420' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M180 0 C280 0, 360 40, 360 120 L360 360 C360 400, 310 420, 180 420 C50 420, 0 400, 0 360 L0 120 C0 40, 80 0, 180 0 Z' fill='black'/%3E%3C/svg%3E");
