selector {
  background: linear-gradient(180deg, #bbf6ff 0%, #ffffff 100%) !important;
}
selector .elementor-widget-divider {
  display: none !important;
}
selector .elementor-main-swiper {
  padding-bottom: 75px !important;
  position: relative !important;
  overflow: visible !important;
}
selector .swiper-slide,
selector .elementor-testimonial,
selector .elementor-testimonial__header,
selector .elementor-testimonial__content {
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
selector .testimonial-box,
selector .elementor-testimonial {
  position: relative;
  padding: 20px 22px 42px 22px !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  text-align: center;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 400px;
  transition: all 0.35s ease;
}
selector .testimonial-box::before,
selector .elementor-testimonial::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 80%;
  pointer-events: none;
  background: url('data:image/svg+xml;utf8,<svg viewBox="0 0 1448 922" fill="none" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="none"><path d="M1356.34 22.1114C924.251 -9.03098 401.784 -5.26023 96.2822 20.8442C61.6385 23.8045 33.5749 49.9675 28.3935 84.3492C-16.1595 379.988 -1.77575 665.634 27.1422 840.09C32.7627 873.997 61.2945 898.845 95.574 901.339C522.111 932.373 968.22 924.218 1352.58 900.702C1387.87 898.543 1417.19 872.807 1422.12 837.791C1448.48 650.255 1462.77 303.276 1423.8 81.3584C1417.99 48.2734 1389.85 24.5262 1356.34 22.1114Z" fill="%23C8102E"/><path d="M1310.14 59.809C923.284 25.3291 446.236 39.496 145.516 60.6607C103.269 63.6341 68.6712 95.1845 62.9364 137.146C29.4612 382.086 38.6299 640.686 61.5967 794.428C67.5946 834.579 101.465 863.647 141.968 866.411C536.13 893.304 947.111 886.341 1303.44 865.744C1345.37 863.32 1380.35 832.847 1385.95 791.215C1408.9 620.527 1420.5 326.102 1387.56 129.398C1381.14 91.0372 1348.89 63.2619 1310.14 59.809Z" fill="white"/></svg>') no-repeat center / 100% 100%;
  z-index: -1;
}
selector .elementor-testimonial__header { display: flex; flex-direction: column; align-items: center; justify-content: center; margin-bottom: 8px; width: 100%; }
selector .elementor-testimonial__image, selector .testimonial-image { width: 95px !important; height: 95px !important; margin: 0 auto 12px auto !important; position: relative; z-index: 2; }
selector .elementor-testimonial__image img, selector .testimonial-image img { width: 95px !important; height: 95px !important; border-radius: 50% !important; border: 5px solid #ffffff !important; box-shadow: 0 4px 14px rgba(0,0,0,0.12) !important; object-fit: cover !important; padding: 0 !important; display: block; transition: all 0.3s ease; }
selector .swiper-slide.swiper-slide-active .elementor-testimonial__image img { border: 4px solid #C8102E !important; box-shadow: 0 6px 18px rgba(200, 16, 46, 0.28) !important; }
selector .elementor-testimonial__cite { display: flex !important; flex-direction: column !important; align-items: center !important; text-align: center !important; }
selector .elementor-testimonial__name, selector .testimonial-name { font-size: 20px !important; font-weight: 800 !important; color: #111827 !important; margin-bottom: 2px !important; text-align: center !important; }
selector .elementor-testimonial__title, selector .testimonial-company { font-size: 14px !important; color: #6B7280 !important; margin-bottom: 6px !important; font-weight: 500 !important; text-align: center !important; }
selector .elementor-testimonial__icon { display: none !important; }
selector .elementor-testimonial__rating, selector .star-rating { text-align: center !important; margin: 4px 0 10px 0 !important; color: #F59E0B !important; font-size: 22px !important; }
selector .elementor-testimonial__content, selector .testimonial-text { font-size: 14px !important; line-height: 1.6 !important; color: #374151 !important; font-style: italic !important; text-align: center !important; padding: 0 8px !important; }
selector .swiper-slide { opacity: 0.65 !important; transform: scale(0.86) !important; transition: transform 0.4s ease, opacity 0.4s ease !important; }
selector .swiper-slide.swiper-slide-active { opacity: 1 !important; transform: scale(1.02) !important; z-index: 5 !important; }
@media (min-width: 1025px) {
  selector .elementor-main-swiper:not(.is-centered) .swiper-slide-active { opacity: 0.65 !important; transform: scale(0.86) !important; z-index: 1 !important; }
  selector .elementor-main-swiper:not(.is-centered) .swiper-slide-active .elementor-testimonial__image img { border: 5px solid #ffffff !important; }
  selector .elementor-main-swiper:not(.is-centered) .swiper-slide-active + .swiper-slide { opacity: 1 !important; transform: scale(1.02) !important; z-index: 5 !important; }
  selector .elementor-main-swiper:not(.is-centered) .swiper-slide-active + .swiper-slide .elementor-testimonial__image img { border: 4px solid #C8102E !important; box-shadow: 0 6px 18px rgba(200, 16, 46, 0.28) !important; }
}
selector .elementor-swiper-button-prev, selector .elementor-swiper-button-next {
  position: absolute !important; top: auto !important; bottom: 12px !important; width: 44px !important; height: 44px !important;
  background-color: #C8102E !important; border-radius: 50% !important; color: #ffffff !important;
  display: flex !important; align-items: center !important; justify-content: center !important;
  cursor: pointer !important; opacity: 1 !important; border: none !important; box-shadow: 0 4px 10px rgba(200, 16, 46, 0.25) !important;
  z-index: 10 !important; margin: 0 !important;
}
selector .elementor-swiper-button-prev::after, selector .elementor-swiper-button-next::after {
  content: "" !important; position: absolute !important; top: -4px !important; left: -4px !important; right: -4px !important; bottom: -4px !important;
  border-radius: 50% !important; border: 1.5px dashed #C8102E !important; pointer-events: none !important; box-sizing: border-box !important;
}
selector .elementor-swiper-button-prev { left: calc(50% - 50px) !important; right: auto !important; }
selector .elementor-swiper-button-next { left: calc(50% + 6px) !important; right: auto !important; }
selector .elementor-swiper-button-prev svg, selector .elementor-swiper-button-next svg { fill: #ffffff !important; width: 14px !important; height: 14px !important; }
